CREATE TABLE IF NOT EXISTS users (user_id TEXT PRIMARY KEY, display_name TEXT, onboarded_at TEXT, digest_opt_out INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY AUTOINCREMENT, ledger_id TEXT NOT NULL, user_id TEXT NOT NULL, paid_by TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('debit','credit')), amount REAL NOT NULL CHECK(amount > 0), category TEXT NOT NULL, subcategory TEXT, description TEXT, txn_date TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('manual','sms','statement','receipt')), raw_input TEXT, deleted_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_entries_ledger_date ON entries(ledger_id, txn_date);
CREATE INDEX IF NOT EXISTS idx_entries_dedup ON entries(ledger_id, amount, txn_date);
CREATE TABLE IF NOT EXISTS pending_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, ledger_id TEXT NOT NULL, user_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('debit','credit')), amount REAL NOT NULL CHECK(amount > 0), category TEXT NOT NULL, description TEXT, txn_date TEXT NOT NULL, source TEXT NOT NULL, raw_input TEXT, reason TEXT NOT NULL DEFAULT 'duplicate', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS budgets (ledger_id TEXT NOT NULL, category TEXT NOT NULL, monthly_limit REAL NOT NULL CHECK(monthly_limit > 0), PRIMARY KEY(ledger_id, category));
CREATE TABLE IF NOT EXISTS payee_memory (user_id TEXT NOT NULL, payee TEXT NOT NULL, category TEXT NOT NULL, PRIMARY KEY(user_id, payee));
CREATE TABLE IF NOT EXISTS conversation_context (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_ctx_user ON conversation_context(user_id, id);
CREATE TABLE IF NOT EXISTS alerts_sent (ledger_id TEXT NOT NULL, category TEXT NOT NULL, month TEXT NOT NULL, threshold INTEGER NOT NULL CHECK(threshold IN (80,100)), sent_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(ledger_id, category, month, threshold));
CREATE TABLE IF NOT EXISTS cost_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, operation TEXT NOT NULL, model TEXT NOT NULL, input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, cost_usd REAL NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
